\[
\begin{aligned}
\cos \theta & =\frac{x}{r} & & \\
x^{2}+y^{2} & =r^{2} & & \\
y^{2} & =(7)^{2}-(-6)^{2} & & 1 / 2 \text { mark for substitution of } x=-6 \text { and } r=7 \\
y^{2} & =13 & & \\
y & = \pm \sqrt{13} & & 1 / 2 \text { mark for solving for } y \\
\tan \theta & =\frac{\sqrt{13}}{6} & & 1 \text { mark for the value of } \tan \theta\left(\frac{1}{2} \text { mark for the quadrant, } \frac{1}{2}\right. \text { mark for the value) }
\end{aligned}
\]

